    def odom_cb(self, data):
        self.odom_idx += 1

        if not self.start_logging:
            return

        # if self.odom_idx % 10 != 0:
        #     return

        timestamp = data.header.stamp.sec

        pose = data.pose.pose.position
        pose_x = pose.x
        pose_y = pose.y
        pose_z = pose.z

        orientation = data.pose.pose.orientation
        orientation_x = orientation.x
        orientation_y = orientation.y
        orientation_z = orientation.z
        orientation_w = orientation.w

        twist_linear = data.twist.twist.linear
        twist_linear_x = twist_linear.x
        twist_linear_y = twist_linear.y
        twist_linear_z = twist_linear.z

        twist_angular = data.twist.twist.angular
        twist_angular_x = twist_angular.x
        twist_angular_y = twist_angular.y
        twist_angular_z = twist_angular.z

        self.csv_writer_odom.writerow([
            timestamp, pose_x, pose_y, pose_z,
            orientation_x, orientation_y, orientation_z, orientation_w,
            twist_linear_x, twist_linear_y, twist_linear_z,
            twist_angular_x, twist_angular_y, twist_angular_z
        ])

        self.file_odom.flush()

    def battery_cb(self, data):
        percentage = data.percentage
        timestamp = data.header.stamp.sec

        self.csv_writer_battery.writerow([timestamp, percentage])
        self.file_battery.flush()

    def imu_cb(self, data):
        if not self.start_logging:
            return

        # self.get_logger().info("---------- IMU -------------")
        # self.get_logger().info(data)
        # self.get_logger().info("-----------------------")

        timestamp = data.header.stamp.sec

        orientation = data.orientation
