    def publish_ack_func(self, msg_type=None, success=None, data=None):
        msg = String()
        msg.data = f"{self.my_ID};{msg_type};{success};{data}"
        self.ack_publisher.publish(msg)        

    def parse_master_message(self, message):
        if message.id != self.current_master or (message.target_id != self.my_ID and message.target_id != -1):
            return
        self.get_logger().info(f"Message received from the master {message.id} : {message.msg}")
        lst = message.msg.split(";")
        func = lst[0]
        if func == "run":
            # func=run means we have to run a dnn model
            model_name = lst[1]
            self.model_running.append(model_name)
            exec("self."+self.model_stored[model_name]['caller_func'])
            self.dnn_load+=1
            self.publish_ack_func(msg_type="ack", success="OK", data=model_name)
        

    def publish_model_map(self):
        # make a publisher in it
        # To publish -> 1. model_stored : [dict] 2. model_running : list
        msg = String()
        msg.data = f"{self.my_ID};{self.model_stored};{self.model_running}"
        self.get_logger().info(f'Model publish : {msg.data}')
        self.model_publisher.publish(msg)

    # To return battery, decrease by 2% each interval (currently 5 seconds)
    def getBattery(self):
        self.current_battery-=2
        return self.current_battery

    # To return memory util, will remain same till load increases
    def getMemory(self):
        current_mem_util = 2 * self.dnn_load
        avail_mem = self.total_compute - current_mem_util
        return avail_mem

    # Sending health data
    def send_health(self):
        batt = self.getBattery()
        memory = self.getMemory()
        msg = String()
        msg.data = f"{self.my_ID};{batt};{memory};{self.total_compute}"
        self.health_publisher.publish(msg)
        self.get_logger().info(f"Publishing : {msg.data}")
    

    def update_fleet_health(self, message):
        self.get_logger().info(f'Health order received from the master : {message.data}')
        temp_health_order=eval(message.data)
        if temp_health_order[0] != self.current_master:
            self.get_logger().info(f'Health order was received from old master...IGNORING')
            return
        self.health_order = temp_health_order
        self.master_status_counter = 0
        self.total_drones_in_fleet = len(self.health_order)
        self.all_drones = set(self.health_order)
        self.absent_counter = {i: 0 for i in self.all_drones}

    def check_master_status(self):
        self.master_status_counter += 5
        if self.master_status_counter > 25:
            # mark master and change your master, if you are master then do something otherwise do following
            self.get_logger().info(f"Master {self.current_master} down!!!")
            self.get_logger().info(f"Current health order {self.health_order}")
            if len(self.health_order)==0:
                return
            self.all_drones.remove(self.current_master)
            self.master_status_counter = 0
            if self.health_order[1] != self.my_ID:
                self.current_master = self.health_order[1]
                time.sleep(3)
                self.publish_model_map()
                _ = self.health_order.pop(0)
            else:
                # do something you are the new master
                self.total_drones_in_fleet -= 1
                self.all_drones.remove(self.my_ID)
                self.current_master = self.my_ID
                self.unsubscribe_master_command()
                self.unsubscribe_master_health()
                self.unsubscribe_master_msg()
                self.create_master_command()
                self.create_master_health()
                self.create_master_msg()
                self.create_slave_health_subscription()
                self.create_slave_model_subscription()
                self.create_slave_msg_subscription()

    # Processing the commands from master drone
    def nav_command_from_master(self, message):
        """
            Message received from the master drone.
            
            The message contains following fields:

            # MasterCommand.msg
            int32 id              # Unique command ID
            string function       # eg. "rc", "acceptance" etc.
            string type           # e.g. "takeoff", "velocity", "land" etc.
            float64 speed         # Target speed in m/s
            float64 x             # Local frame X coordinate
            float64 y             # Local frame Y coordinate
            float64 z             # Local frame Z coordinate
            float64 yaw           # Desired yaw angle in radians
            float64 height        # Target altitude in meters
            float64 lat           # GPS latitude (WGS84)
            float64 longitude     # GPS longitude (WGS84)           
        """
        self.get_logger().info(f"Command Received from : {message.id}")
        
        if int(message.id) != self.current_master:
            return
        
        command={}
        command['function'] = message.function
        command['type'] = message.type
        command['speed'] = message.speed
        command['x'] = message.x
        command['y'] = message.y
        command['z'] = message.z
        command['yaw'] = message.yaw
        command['height'] = message.height
        command['lat'] = message.lat
        command['longitude'] = message.longitude

        if command["function"] == "rc":
            self.drone_navigation(command)
        else:
            function = command['function']
            self.get_logger().info(f"Undefined function type in master message : {function}")



